"""Disposable loopback API with a reproducible zero-quantity defect."""

import argparse
from http.server import BaseHTTPRequestHandler, HTTPServer
import json
from pathlib import Path
from urllib.parse import urlsplit


def create_server(port=8771, fixed=False):
    orders = {}
    next_id = 1

    class Handler(BaseHTTPRequestHandler):
        def setup(self):
            super().setup()
            self.connection.settimeout(5)

        def log_message(self, format, *args):
            pass

        def send_json(self, status, data=None):
            body = b"" if data is None else json.dumps(data).encode("utf-8")
            self.send_response(status)
            if data is not None:
                self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_GET(self):
            route = urlsplit(self.path).path
            if route == "/health":
                return self.send_json(200, {"status": "ready", "mode": "fixed" if fixed else "faulty"})
            if route == "/openapi.json":
                schema = json.loads(Path(__file__).with_name("openapi.json").read_text())
                schema["servers"] = [{"url": f"http://127.0.0.1:{self.server.server_port}"}]
                return self.send_json(200, schema)
            if route.startswith("/orders/"):
                order = orders.get(route.removeprefix("/orders/"))
                return self.send_json(200, order) if order else self.send_json(404, {"error": "Order not found"})
            return self.send_json(404, {"error": "Route not found"})

        def do_POST(self):
            nonlocal next_id
            route = urlsplit(self.path).path
            if route == "/reset":
                orders.clear()
                next_id = 1
                return self.send_json(200, {"reset": True})
            if route != "/orders":
                return self.send_json(404, {"error": "Route not found"})
            try:
                length = int(self.headers.get("Content-Length", "0"))
            except ValueError:
                return self.send_json(400, {"error": "Invalid content length"})
            if not 0 < length <= 4096:
                return self.send_json(400, {"error": "Provide one small JSON order"})
            try:
                data = json.loads(self.rfile.read(length))
            except (ValueError, UnicodeDecodeError):
                return self.send_json(400, {"error": "Invalid JSON"})
            if (not isinstance(data, dict) or set(data) != {"quantity"}
                    or type(data["quantity"]) is not int or not 0 <= data["quantity"] <= 100):
                return self.send_json(400, {"error": "quantity must be an integer from 0 through 100"})
            quantity = data["quantity"]
            total = quantity * 10
            try:
                unit_price = 10 if fixed else total // quantity
            except ZeroDivisionError:
                return self.send_json(500, {"error": "Zero-quantity unit-price defect"})
            if len(orders) >= 10000:
                return self.send_json(429, {"error": "Fixture full; reset before another run"})
            identifier = str(next_id)
            next_id += 1
            order = {"id": identifier, "quantity": quantity, "total": total, "unitPrice": unit_price}
            orders[identifier] = order
            return self.send_json(201, order)

        def do_DELETE(self):
            route = urlsplit(self.path).path
            if not route.startswith("/orders/"):
                return self.send_json(404, {"error": "Route not found"})
            identifier = route.removeprefix("/orders/")
            if orders.pop(identifier, None) is None:
                return self.send_json(404, {"error": "Order not found"})
            return self.send_json(204)

    return HTTPServer(("127.0.0.1", port), Handler)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--port", type=int, default=8771)
    parser.add_argument("--fixed", action="store_true")
    args = parser.parse_args()
    with create_server(args.port, args.fixed) as server:
        print(f"Ready on http://127.0.0.1:{server.server_port}; mode={'fixed' if args.fixed else 'faulty'}. Ctrl+C stops the server.", flush=True)
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass
"""Run the pinned local API check and preserve output with scoped UTF-8 encoding."""

import argparse
from importlib.metadata import version
import json
import os
from pathlib import Path
import subprocess
import sys


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--port", type=int, default=8771)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    output = args.output.resolve()
    if output.exists() and any(output.iterdir()):
        parser.error("Choose a new output directory so earlier reports are preserved.")
    output.mkdir(parents=True, exist_ok=True)
    entrypoint = Path(sys.executable).with_name("schemathesis.exe" if os.name == "nt" else "schemathesis")
    command = [str(entrypoint), "--no-color", "run", f"http://127.0.0.1:{args.port}/openapi.json",
               "--phases", "coverage", "--mode", "positive", "--checks", "not_a_server_error",
               "--max-failures", "1", "--max-time", "20", "--seed", "20261106", "--workers", "1",
               "--report", "junit", "--report-junit-path", str(output / "junit.xml")]
    record = {"command": command, "environment_overrides": {"PYTHONIOENCODING": "utf-8"},
              "exit_code": None, "scope": "Coverage phase, positive generation, server-error check. Read reports for skipped work."}
    try:
        record["version"] = version("schemathesis")
        if record["version"] != "4.33.1":
            raise RuntimeError("Install the pinned Schemathesis 4.33.1 environment.")
        result = subprocess.run(command, env={**os.environ, **record["environment_overrides"]},
                                capture_output=True, encoding="utf-8", timeout=40)
        record["exit_code"] = result.returncode
        (output / "stdout.txt").write_text(result.stdout, encoding="utf-8")
        (output / "stderr.txt").write_text(result.stderr, encoding="utf-8")
    except subprocess.TimeoutExpired as error:
        record["error"] = "Incomplete: the wrapper time limit expired."
        for name, value in [("stdout", error.stdout), ("stderr", error.stderr)]:
            text = value.decode("utf-8", errors="replace") if isinstance(value, bytes) else value or ""
            (output / f"{name}.txt").write_text(text, encoding="utf-8")
    except Exception as error:
        record["error"] = f"Setup or execution failed: {type(error).__name__}: {error}"
    (output / "run.json").write_text(json.dumps(record, indent=2, ensure_ascii=True) + "\n", encoding="ascii")
    print(f"Reports: {output}. Process status: {record['exit_code']}. Inspect the reports for findings and incomplete work.")
    raise SystemExit(record["exit_code"] if record["exit_code"] is not None else 2)
"""Replay the known failure, or confirm the corrected behavior, on loopback."""

import argparse
import json
from urllib.error import HTTPError
from urllib.request import Request, urlopen


def request(port, method, route, body=None):
    data = None if body is None else json.dumps(body).encode("utf-8")
    operation = Request(f"http://127.0.0.1:{port}{route}", data=data, method=method,
                        headers={"Content-Type": "application/json"})
    try:
        response = urlopen(operation, timeout=5)
    except HTTPError as error:
        response = error
    with response:
        raw = response.read()
        return response.status, json.loads(raw) if raw else None


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--port", type=int, default=8771)
    parser.add_argument("--expect-fixed", action="store_true")
    parser.add_argument("--reset", action="store_true")
    args = parser.parse_args()
    if args.reset:
        status, body = request(args.port, "POST", "/reset")
        print(json.dumps({"status": status, "body": body}))
        raise SystemExit(0 if status == 200 else 1)
    health, details = request(args.port, "GET", "/health")
    assert health == 200, (health, details)
    status, body = request(args.port, "POST", "/orders", {"quantity": 0})
    print(json.dumps({"request": {"method": "POST", "path": "/orders", "body": {"quantity": 0}},
                      "status": status, "response": body, "mode": details["mode"]}, indent=2))
    assert status == (201 if args.expect_fixed else 500), (status, body)
    if args.expect_fixed:
        assert body["total"] == 0 and body["unitPrice"] == 10
        fetched, order = request(args.port, "GET", f"/orders/{body['id']}")
        assert fetched == 200 and order == body
        print("Created order was read back successfully.")

